	@Test
	void scopeMutatesOnlyOwnerFreeHolderHead() throws Exception {
		assertNoThreadLocalMutation("LmdbSailStore.class", "enterReadResourceContext");
		assertNoThreadLocalMutation("LmdbSailStore$ReadResourceContext.class", "close");
		Class<?> state = Class.forName(LmdbSailStore.class.getName() + "$ReadResourceState");
		assertTrue(Modifier.isStatic(state.getModifiers()));
		assertEquals(List.of("current"), Arrays.stream(state.getDeclaredFields()).map(f -> f.getName()).toList());
	}

	@Test
	void nestedEmptyFramesKeepDynamicIdentityUnion(@TempDir Path dir) throws Exception {
		LmdbStore store = initialized(dir);
		try {
			var backing = store.getBackingStore();
			var first = mock(LmdbSailStore.ReadViewLease.class);
			var second = mock(LmdbSailStore.ReadViewLease.class);
			List<LmdbSailStore.ReadViewLease> dynamic = new ArrayList<>(List.of(first));
			try (var outer = backing.enterReadResourceContext(() -> dynamic);
					var empty = backing.enterReadResourceContext(List::of)) {
				assertEquals(List.of(first), backing.currentReadResourceViews());
				dynamic.add(second);
				dynamic.add(null);
				try (var duplicate = backing.enterReadResourceContext(() -> List.of(first))) {
					var actual = backing.currentReadResourceViews();
					assertEquals(2, actual.size());
					assertTrue(actual.stream().anyMatch(v -> v == first));
					assertTrue(actual.stream().anyMatch(v -> v == second));
				}
				assertEquals(2, backing.currentReadResourceViews().size());
			}
			assertTrue(backing.currentReadResourceViews().isEmpty());
		} finally {
			store.shutDown();
		}
	}

