	private static void assertNoThreadLocalMutation(String resource, String name) throws Exception {
		try (var bytes = LmdbSailStore.class.getResourceAsStream(resource)) {
			var method = ClassFile.of()
					.parse(bytes.readAllBytes())
					.methods()
					.stream()
					.filter(m -> m.methodName().equalsString(name))
					.findFirst()
					.orElseThrow();
			var changes = method.code()
					.orElseThrow()
					.elementList()
					.stream()
					.filter(InvokeInstruction.class::isInstance)
					.map(InvokeInstruction.class::cast)
					.filter(i -> i.owner().asInternalName().equals("java/lang/ThreadLocal"))
					.map(i -> i.name().stringValue())
					.filter(n -> n.equals("set") || n.equals("remove"))
					.toList();
			assertEquals(List.of(), changes);
		}
	}
